89	export type SlaStatus = "ok" | "warning" | "breached";
90	
91	export function getSlaStatus(slaDueAt: string, now = "2026-04-10T12:00:00Z"): SlaStatus {
92	  const dueMs = new Date(slaDueAt).getTime();
93	  const nowMs = new Date(now).getTime();
94	  const diffHours = (dueMs - nowMs) / (1000 * 60 * 60);
95	  if (diffHours < 0) return "breached";
96	  if (diffHours < 24) return "warning";
97	  return "ok";
98	}
